#include "stdlib/math/base/special/ellipkf.h"
#include "stdlib/math/base/special/ellipk.h"

/**
* Computes the complete elliptic integral of the first kind for a single-precision floating-point number.
*
* @param x    input value
* @return     evaluated elliptic integral
*
* @example
* float out = stdlib_base_ellipkf( 0.5f );
* // returns ~1.854f
*/
float stdlib_base_ellipkf( const float m ) {
	// TODO: Replace with a better implementation once available:
	return (float)stdlib_base_ellipk( (double)m );
}
